@startuml

class Person {
  + FirstName : string
  + FamilyName : string
  + BirthDate : date
}

class Trainer {
  + Diploma : string
}

class Member {
}

class Center {
  + Name : string
  + Address : string
}

class Room {
  + RoomNumber : int
  + MaxCapacity : int
}

abstract class Session {
  + Date : date
  + StartHour : time
}

class IndividualSession {}

class GroupSession {
  + Type : string
}

class Participation {
}

Trainer --|> Person
Member --|> Person

Center "1" *-- "1..*" Room
Room "1" -- "0..*" Session

GroupSession --|> Session
IndividualSession --|> Session

Trainer "1" -- "*" GroupSession : supervises
Trainer "1" -- "*" Participation : performs
Member "1" -- "*" Participation : attends

Participation "*" -- "1" Session
Participation "*" -- "1" Person

@enduml

